{
  "name": "@sinyotsai/opencode-tokenusage",
  "version": "0.2.3",
  "type": "module",
  "description": "Session-scoped token usage, TTFT, TPS and routed model cards for the opencode sidebar",
  "author": "sinyotsai",
  "license": "MIT",
  "files": [
    "server.js",
    "stats.js",
    "tui.js"
  ],
  "publishConfig": {
    "access": "public"
  },
  "engines": {
    "node": ">=22",
    "opencode": ">=2.2.0 <3"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "token-usage",
    "litellm",
    "v2"
  ],
  "main": "./server.js",
  "exports": {
    "./server": {
      "import": "./server.js",
      "default": "./server.js"
    },
    ".": {
      "import": "./server.js",
      "default": "./server.js"
    },
    "./tui": {
      "import": "./tui.js",
      "default": "./tui.js"
    }
  },
  "dependencies": {
    "@opentui/core": "^0.5.11",
    "@opentui/solid": "^0.5.11",
    "solid-js": "^1.9.12"
  }
}
